override def persistEntityModifications(modifications, waitUntilQueryReflectsModifications) = {
  for (modification <- modifications) entityPermissions.checkAllowedForWrite(modification)
  val future = entityAccess.persistEntityModificationsAsync(modifications)
  if (waitUntilQueryReflectsModifications) Await.ready(future, atMost = Duration.Inf)
}
